using System; using System.Collections.Generic; using System.Linq; using UnityEngine;  public abstract class ItemContainerBase : ScriptableObject, IItemContainer {     [SerializeField] protected List<ItemSlotData> items = new List<ItemSlotData>();     [SerializeField] protected int maxSlots = 10; // 기본값, 상속받아서 변경 가능      public IReadOnlyList<ItemSlotData> Items => items;     public bool HasItems => items.Count > 0;     public virtual int SlotCount => maxSlots;      public event Action OnContainerChanged;      // 이벤트 발생 헬퍼     protected void NotifyChanged() => OnContainerChanged?.Invoke();      // ---- 공통 구현 ----     public virtual bool AddItem(int itemID, int count)     {         if (count <= 0) return false;          var slot = items.Find(s => s.itemID == itemID);         if (slot != null)         {             slot.count += count;         }         else         {             // 슬롯 여유 체크             if (items.Count >= maxSlots)             {                 Debug.LogWarning($"[{GetType().Name}] 슬롯이 가득 찼습니다!");                 return false;             }             items.Add(new ItemSlotData { itemID = itemID, count = count });         }          NotifyChanged();         return true;     }      public virtual bool RemoveItem(int itemID, int count)     {         var slot = items.Find(s => s.itemID == itemID);         if (slot == null || slot.count < count) return false;          slot.count -= count;         if (slot.count <= 0) items.Remove(slot);          NotifyChanged();         return true;     }      public int GetItemCount(int itemID)     {         var slot = items.Find(s => s.itemID == itemID);         return slot?.count ?? 0;     }      public virtual void Clear()     {         items.Clear();         NotifyChanged();     }      //  컨테이너 간 이동     public bool TransferTo(IItemContainer target, int itemID, int count)     {         if (target == null) return false;         if (GetItemCount(itemID) < count) return false;          // 대상에 먼저 추가 시도         if (!target.AddItem(itemID, count)) return false;          // 성공하면 여기서 제거         RemoveItem(itemID, count);         return true;     }      public bool TransferAllTo(IItemContainer target)     {         if (target == null || !HasItems) return false;          // 복사본으로 순회 (수정 중 컬렉션 변경 방지)         var itemsCopy = items.ToList();         foreach (var slot in itemsCopy)         {             target.AddItem(slot.itemID, slot.count);         }          Clear();         return true;     } }